-- Run only in an isolated local checkpoint database. All fixture objects roll back.
BEGIN;
CREATE SCHEMA checkpoint_owner_upgrade;
SET LOCAL search_path = checkpoint_owner_upgrade;
CREATE TYPE "OwnerTransactionType" AS ENUM ('INVESTMENT','WITHDRAWAL','OWNER_LOAN');
CREATE TABLE users (id UUID PRIMARY KEY, "companyId" UUID NOT NULL, name TEXT, role TEXT);
CREATE TABLE ledger_accounts (id UUID PRIMARY KEY, "companyId" UUID NOT NULL, name TEXT);
CREATE TABLE owner_financial_accounts (id UUID PRIMARY KEY,"companyId" UUID NOT NULL,"userId" UUID NOT NULL,"capitalLedgerId" UUID NOT NULL,"drawingsLedgerId" UUID NOT NULL,"loanLedgerId" UUID NOT NULL);
CREATE TABLE owner_transactions (id UUID PRIMARY KEY,"ownerFinancialAccountId" UUID NOT NULL,type "OwnerTransactionType" NOT NULL,amount DECIMAL(18,2));
INSERT INTO users VALUES ('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000010','Existing partner','DATA_ENTRY');
INSERT INTO ledger_accounts VALUES ('00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000010','Former owner Capital');
INSERT INTO owner_financial_accounts VALUES
('00000000-0000-4000-8000-000000000030','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000021','00000000-0000-4000-8000-000000000022'),
('00000000-0000-4000-8000-000000000031','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000099','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000021','00000000-0000-4000-8000-000000000022');
INSERT INTO owner_transactions VALUES ('00000000-0000-4000-8000-000000000040','00000000-0000-4000-8000-000000000030','WITHDRAWAL',25);
\i prisma/migrations/20261012080000_owner_identity_and_withdrawal_types/migration.sql
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM owner_financial_accounts WHERE id='00000000-0000-4000-8000-000000000030' AND name='Existing partner' AND "userId"='00000000-0000-4000-8000-000000000001' AND "capitalLedgerId"='00000000-0000-4000-8000-000000000020' AND "isActive") THEN RAISE EXCEPTION 'Linked identity or ledger changed'; END IF;
 IF NOT EXISTS (SELECT 1 FROM owner_financial_accounts WHERE id='00000000-0000-4000-8000-000000000031' AND name='Former owner' AND "userId" IS NULL AND "legacyUserId"='00000000-0000-4000-8000-000000000099') THEN RAISE EXCEPTION 'Dangling identity not preserved'; END IF;
